param([string]$ProjectRoot=(Split-Path -Parent $PSScriptRoot))
$ErrorActionPreference='Stop'
$raw=Get-Content (Join-Path $ProjectRoot 'data\raw_candidates\egypt_presidency_honours.jsonl')|Where-Object{$_}|ForEach-Object{$_|ConvertFrom-Json}
$families=[Collections.Generic.List[object]]::new();$conflicts=[Collections.Generic.List[object]]::new()
foreach($r in $raw){$variants=@($r.grades_or_classes|ForEach-Object{[ordered]@{label=$_;status='official_grade_or_configuration_text';image_status='missing'}});$norm= switch($r.local_difference_status){'difference_candidate'{'new_official_family_candidate'}'existing_catalogue_variant'{'matched_existing_family_new_official_variant_structure'}'existing_catalogue_match'{'matched_existing_family_official_corroboration'}default{'needs_family_match_review'}};$family=[ordered]@{scope_id='egypt';family_id=$r.candidate_key;preferred_name=$r.page_title_en;original_names=@($r.original_names);arabic_name=$r.page_title_ar;date_candidates=@($r.date_candidates);date_basis=$r.date_basis;normalization_status=$norm;variants=$variants;material_clues=$r.grade_material_clues;design_summary=$r.design_summary;official_pages=@($r.detail_page_ar,$r.detail_page_en);cache_files=@($r.cache_files);image_status='official_text_only_no_object_image'};$families.Add($family);if($r.grade_material_clues -match 'language difference'){ $conflicts.Add([ordered]@{family_id=$r.candidate_key;type='MATERIAL_WORDING_LANGUAGE_DIFFERENCE';values=$r.grade_material_clues;status='UNRESOLVED'})}}
$summary=[ordered]@{input_rows=$raw.Count;normalized_families=$families.Count;new_official_family_candidates=@($families|Where-Object normalization_status -eq 'new_official_family_candidate').Count;matched_existing_families=@($families|Where-Object normalization_status -match '^matched_existing').Count;needs_family_match_review=@($families|Where-Object normalization_status -eq 'needs_family_match_review').Count;official_variant_or_grade_groups=@($families.variants|ForEach-Object{$_}).Count;families_with_object_images=0;conflicts=$conflicts.Count}
$out=[ordered]@{schema_version='2.0';as_of='2026-09-26';batch_id='egypt_official_normalized_batch2';status='normalized_official_text_not_html_approved';summary=$summary;families=@($families)};$outPath=Join-Path $ProjectRoot 'data\normalized\egypt_official_normalized_batch2.json';$cfPath=Join-Path $ProjectRoot 'data\conflicts\egypt_official_normalization_batch2.json';$cpPath=Join-Path $ProjectRoot 'data\checkpoints\egypt_official_normalization_batch2_2026-09-26.json';[IO.File]::WriteAllText($outPath,($out|ConvertTo-Json -Depth 15),[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText($cfPath,([ordered]@{schema_version='2.0';as_of='2026-09-26';conflicts=@($conflicts)}|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false));[IO.File]::WriteAllText($cpPath,([ordered]@{schema_version='2.0';as_of='2026-09-26';batch='egypt_official_normalized_batch2';summary=$summary;next_action='Use institutional or openly licensed object sources to bind complete images for the Republic Collar, Nile Sash and Medal of Work first.'}|ConvertTo-Json -Depth 8),[Text.UTF8Encoding]::new($false));$summary|ConvertTo-Json -Depth 5
